corrected_code:
from prometheus_client import Counter

FEATURE_USAGE_COUNTER = Counter(
    "tenant_feature_usage_total",
    "Billable feature usage",
    ["organization_id", "feature_name"]
)

@router.post("/telemetry/track-feature-hit")
async def track_feature(
    body: FeatureHitSchema,
    current_user: User = Depends(get_current_user)
):
    if body.organization_id != current_user.organization_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: cannot record telemetry for foreign organization")

    FEATURE_USAGE_COUNTER.labels(
        organization_id=current_user.organization_id,
        feature_name=body.feature_name
    ).inc(body.hit_count)
    return {"recorded": True}
